@js:
/* 站址自动推导：优先取引擎传入的当前页 URL（换域后自动跟随），取不到才回落。 */
var B = (function () {
  var u = (typeof baseUrl !== 'undefined' && baseUrl) ? String(baseUrl) : '';
  var m = u.match(/^https?:\/\/[^\/]+/);
  return m ? m[0] : 'https://www.photo13.com';
})();
var CSS = '<style>img{max-width:100%;height:auto;display:block;margin:8px auto}</style>';
var h = String(result == null ? '' : result);
/* 抓一页 HTML 里的图床直链（src= 前必须是空白，避免误抓 data-src 占位） */
function pick(html) {
  var out = [];
  var re = /\ssrc="(https?:\/\/img[^"']+\.(?:jpg|jpeg|png|webp))"/gi;
  var m;
  while ((m = re.exec(html))) { if (out.indexOf(m[1]) < 0) out.push(m[1]); }
  return out;
}
var list = pick(h);
/* WordPress nextpage 分页（/m/{id}/{n}，每页约 10 张）：逐页抓齐，上限 30 页 */
var urls = [];
var re2 = /<a[^>]*class="post-page-numbers"[^>]*>/g;
var m2;
while ((m2 = re2.exec(h))) {
  var hu = m2[0].match(/href="([^"]+)"/);
  if (hu && urls.indexOf(hu[1]) < 0) urls.push(hu[1]);
}
if (urls.length > 30) urls = urls.slice(0, 30);
for (var i = 0; i < urls.length; i++) {
  try {
    var t = String(java.ajax(urls[i]) || '');
    if (t.length > 1000) {
      var b = pick(t);
      for (var j = 0; j < b.length; j++) { if (list.indexOf(b[j]) < 0) list.push(b[j]); }
    }
  } catch (e) {}
}
var out = CSS;
for (var k = 0; k < list.length; k++) { out += '<img src="' + list[k] + '"/>'; }
out;
